code2='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    labels = [[-1] * w for _ in range(h)]
    objects = []
    label = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or labels[r][c] != -1:
                continue
            stack = [(r, c)]
            labels[r][c] = label
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and labels[ny][nx] == -1:
                            labels[ny][nx] = label
                            stack.append((ny, nx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            objects.append((min(rs), max(rs), min(cs), max(cs)))
            label += 1

    by_row = {}
    by_col = {}
    for r0, r1, c0, c1 in objects:
        center_r, center_c = (r0 + r1) // 2, (c0 + c1) // 2
        by_row.setdefault(center_r, []).append((center_c, r0, r1, c0, c1))
        by_col.setdefault(center_c, []).append((center_r, r0, r1, c0, c1))

    for row, group in by_row.items():
        group.sort()
        for left, right in zip(group, group[1:]):
            for c in range(left[4] + 1, right[3]):
                out[row][c] = 1
    for col, group in by_col.items():
        group.sort()
        for top, bottom in zip(group, group[1:]):
            for r in range(top[2] + 1, bottom[1]):
                out[r][col] = 1
    return out
'''
